"""Independent verification of reduce.py (Vertex Cover -> Dominating Set).

We implement brute-force solvers for both problems from the definitions in
problems.py, enumerate many small instances, reduce each one, and compare the
answers.  We also validate that every produced instance is a well-formed
DominatingSet instance.
"""

from __future__ import annotations

import itertools
import random
from typing import Any

import problems
from problems import SOURCE, TARGET
from reduce import reduce


# ----------------------------------------------------------------------
# Brute-force solvers (written from the definitions, not from reduce.py)

def _is_vertex_cover(n: int, edges: list[list[int]], chosen: set[int]) -> bool:
    for u, v in edges:
        if u not in chosen and v not in chosen:
            return False
    return True


def _is_dominating_set(n: int, edges: list[list[int]], chosen: set[int]) -> bool:
    dominated = set(chosen)
    for u, v in edges:
        if u in chosen:
            dominated.add(v)
        if v in chosen:
            dominated.add(u)
    return len(dominated) == n


def min_vertex_cover(n: int, edges: list[list[int]]) -> int:
    """Minimum size of a vertex cover, or +inf if none (never happens)."""
    best = None
    for r in range(n + 1):
        for combo in itertools.combinations(range(n), r):
            if _is_vertex_cover(n, edges, set(combo)):
                return r
    return None


def min_dominating_set(n: int, edges: list[list[int]]) -> int:
    """Minimum size of a dominating set."""
    for r in range(n + 1):
        for combo in itertools.combinations(range(n), r):
            if _is_dominating_set(n, edges, set(combo)):
                return r
    return None


def solve_vc(instance: dict[str, Any]) -> bool:
    n = instance["n"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    return min_vertex_cover(n, instance["edges"]) <= k


def solve_ds(instance: dict[str, Any]) -> bool:
    n = instance["n"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    return min_dominating_set(n, instance["edges"]) <= k


# ----------------------------------------------------------------------
# Instance enumeration

def all_graphs(n: int):
    """Yield every simple undirected graph on n labelled vertices."""
    possible = [(u, v) for u in range(n) for v in range(u + 1, n)]
    for mask in range(1 << len(possible)):
        edges = [list(e) for i, e in enumerate(possible) if mask & (1 << i)]
        yield edges


def run() -> tuple[int, int, list[str]]:
    tests_run = 0
    tests_passed = 0
    failures: list[str] = []

    def check(instance: dict[str, Any], label: str) -> None:
        nonlocal tests_run, tests_passed
        tests_run += 1
        SOURCE.validate(instance)
        reduced = reduce(instance)
        TARGET.validate(reduced)  # must be a well-formed target instance
        expected = solve_vc(instance)
        got = solve_ds(reduced)
        if expected == got:
            tests_passed += 1
        else:
            failures.append(
                f"{label}: source={instance} expected={expected} "
                f"reduced={reduced} got={got}"
            )

    # Exhaustive over all graphs on 0..6 vertices and a range of k values.
    for n in range(0, 7):
        for edges in all_graphs(n):
            for k in range(-1, n + 2):
                check({"n": n, "edges": edges, "k": k}, f"exhaustive n={n}")

    # Random larger instances.
    rng = random.Random(12345)
    for _ in range(3000):
        n = rng.randint(0, 9)
        possible = [(u, v) for u in range(n) for v in range(u + 1, n)]
        rng.shuffle(possible)
        m = rng.randint(0, len(possible))
        edges = [list(e) for e in possible[:m]]
        k = rng.randint(-2, n + 2)
        check({"n": n, "edges": edges, "k": k}, "random")

    return tests_run, tests_passed, failures


if __name__ == "__main__":
    tests_run, tests_passed, failures = run()
    print(f"tests_run={tests_run} tests_passed={tests_passed}")
    if failures:
        print("FAILURES:")
        for f in failures[:20]:
            print(" ", f)
    else:
        print("all tests passed")
